pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // airdrop requires hasNoBalance (tokenBalance==0) and supportsToken, which calls Bank(msg.sender).
        // The caller must be a contract that implements supportsToken() returning the correct bytes32.
        // Deploy a helper that returns the required value.
        Helper helper = new Helper();
        address callerAddr = address(helper);
        // The function airdrop will internally call Bank(msg.sender).supportsToken(), which for the helper
        // is implemented to return the correct keccak256.
        uint256 balanceBefore = c.tokenBalance(callerAddr);
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }
        // Ensure the fuzzer can explore both success and revert cases;
        // success requires the caller has no balance and returns correct token support.
        if (ok) {
            assertTrue(c.tokenBalance(callerAddr) == balanceBefore + 20);
        }
        // If it reverts, the balance must not have changed.
        // The reference contract can succeed for an admissible caller;
        // the buggy version always fails (require(false)), so it never increases balance.
        // In the buggy version, ok is always false, so the assertion above is never checked,
        // but the reference will succeed at least sometimes and the assertion holds.
    }
}

contract Helper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

