pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address bank) public {
        vm.assume(actor != address(0) && bank != address(0));
        vm.assume(actor.code.length == 0 && bank.code.length > 0);
        // The caller must have no tokens and the bank must return the correct supportsToken
        uint256 balanceBefore = c.tokenBalance(actor);
        vm.assume(balanceBefore == 0);
        // bank must be an address with code that implements supportsToken correctly
        // We use the fuzzer-provided address as a Bank-like contract; since we cannot mock calls,
        // we assume an externally deployed Bank or a helper is not required because the require
        // in supportsToken checks msg.sender; the caller is actor, so Bank(msg.sender) must be a contract
        // that returns keccak256("Nu Token") from supportsToken(). To satisfy this without a hardcoded
        // scenario, we let the fuzzer provide the bank address; the test will revert if the supportsToken
        // check fails, but for passes that revert, the final balance remains 0.
        vm.prank(actor);
        // The call may revert if Bank(msg.sender) doesn't implement supportsToken correctly or if balance non-zero
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.airDrop.selector));
        uint256 balanceAfter = c.tokenBalance(actor);
        // If the call succeeded, balanceAfter must equal 20; otherwise it remains 0 (the original balance)
        assertTrue(!ok || balanceAfter == 20);
    }
}

