import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // Track total successful airdrops
    uint256 public airdropCount;

    function setUp() public {
        c = new C();
        airdropCount = 0;
    }

    function testFuzz_property(address[] memory callers) public {
        // Bound the number of callers to keep gas manageable
        vm.assume(callers.length >= 1 && callers.length <= 10);

        // Ensure all callers are unique and non-zero
        for (uint256 i = 0; i < callers.length; i++) {
            vm.assume(callers[i] != address(0));
            for (uint256 j = i + 1; j < callers.length; j++) {
                vm.assume(callers[i] != callers[j]);
            }
        }

        // Deploy a Bank contract that passes supportsToken check
        Bank bank = new Bank();

        // Perform airdrops for each caller, using the bank's address as the caller
        // Since the caller must support Nu Token, we deploy a Bank at the caller's address
        // But we cannot deploy at arbitrary addresses. Instead, we use the Bank as the caller.
        // The modifier supportsToken checks Bank(msg.sender).supportsToken(), so msg.sender must be a Bank.
        // We deploy one Bank and use it as the caller for all airdrops.
        // However, hasNoBalance requires tokenBalance[msg.sender] == 0, so each caller can only airdrop once.
        // To fuzz multiple callers, we need each caller to be a Bank that passes supportsToken.
        // We can deploy a Bank for each caller by using CREATE2 or by precomputing addresses, but
        // we cannot deploy at arbitrary addresses. The simplest: use the same Bank address as the caller
        // for all, but then only one airdrop succeeds because of hasNoBalance. The fuzzer will find
        // that only one airdrop can happen, so the total supply is always 20. That doesn't distinguish.
        // We need multiple successful airdrops. Since the caller must be a Bank contract, we can
        // deploy multiple Bank contracts and use their addresses as callers. But we need to know their
        // addresses before deploying them to pass them as fuzz parameters. Alternatively, we can
        // deploy a BankFactory that deploys Bank contracts and returns their addresses, but that's
        // additional complexity. A simpler approach: the fuzzer provides an array of addresses, and we
        // assume each is a Bank by using vm.etch to give them the Bank bytecode? But vm.etch is a
        // cheatcode that's not allowed? The rules say NO other vm.* cheatcodes beyond the listed ones.
        // vm.etch is not listed, so it's REJECTED.
        // We need an adversarial helper that behaves like a Bank for supportsToken but allows multiple
        // distinct callers. Actually, the supportsToken modifier calls Bank(msg.sender).supportsToken().
        // If we want multiple callers, each caller must have code that returns the correct bytes32.
        // We can deploy a single helper contract that can be used by multiple callers via delegatecall?
        // No, the modifier uses msg.sender. The easiest: use a single caller (the Bank) and assert on
