        UserWithSupportsToken helper = new UserWithSupportsToken{salt: bytes32(uint256(uint160(caller)))}(c);
        // Set tokenBalance of helper in C to startingBalance
        vm.store(address(c), keccak256(abi.encode(address(helper), uint256(0))), bytes32(startingBalance));

        // Call airDrop as helper
        bool success;
        vm.prank(address(helper));
        try c.airDrop() {
            success = true;
        } catch {
            success = false;
        }

        if (success) {
            uint256 balance = c.tokenBalance(address(helper));
            assertTrue(balance == 20);
        } else {
            // If it reverted, that's fine for reference, bug might also revert for some inputs but not all.
            // The property only asserts on successful calls, which is fine.
        }
    }
}

// Helper contract that the user must be to pass supportsToken check.
// It implements supportsToken() returning the correct hash.
contract UserWithSupportsToken {
    C public c;
    constructor(C _c) {
        c = _c;
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

